import json
import numpy as np

DATA_DIR = '/root/autodl-tmp/structfuse/full_m2_training_data'

for seed in [42, 43, 44]:
    print(f'=== Seed {seed} ===')

    # Stream through files in parallel
    files = {}
    for s in ['random', 'embedding_distance', 'dataflow_aware', 'bm25']:
        files[s] = open(f'{DATA_DIR}/train_{s}_s{seed}.jsonl')

    overlaps = {'bm25_vs_emb': [], 'bm25_vs_random': [], 'bm25_vs_dataflow': []}
    count = 0

    while True:
        lines = {}
        for s, f in files.items():
            line = f.readline()
            if not line:
                break
            lines[s] = line
        if len(lines) < 4:
            break

        negs = {}
        for s, line in lines.items():
            d = json.loads(line)
            negs[s] = set(d['neg_candidates'])

        n = len(negs['bm25'])
        if n > 0:
            overlaps['bm25_vs_emb'].append(len(negs['bm25'] & negs['embedding_distance']) / n)
            overlaps['bm25_vs_random'].append(len(negs['bm25'] & negs['random']) / n)
            overlaps['bm25_vs_dataflow'].append(len(negs['bm25'] & negs['dataflow_aware']) / n)
        count += 1

    for f in files.values():
        f.close()

    for k, v in overlaps.items():
        arr = np.array(v)
        print(f'  {k}: mean={arr.mean():.3f}, std={arr.std():.3f}, median={np.median(arr):.3f}')
    print(f'  total records compared: {count}')
    print()

print('Done!')
EOF
